package library_book_service.support;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Runtime support for DSL object-literal expressions ({@code
 * visitor_expressions.visit_object_literal}).
 *
 * <p>Builds an ordered {@code Map<String, Object>} from alternating key/value varargs -- {@code
 * Map.of(...)} provides no key-insertion-order guarantee, and generated code (JSON response bodies,
 * {@code Entity.fromMap(...)} construction) needs the author-declared key order preserved.
 *
 * <p>Auto-generated by datrix-codegen-java. Do not edit manually.
 */
public final class MapSupport {

  private MapSupport() {}

  /**
   * Build an ordered map from alternating {@code "key", value, "key", value, ...} pairs.
   *
   * @throws IllegalArgumentException if an odd number of arguments is supplied.
   */
  public static Map<String, Object> _datrixOrderedMap(Object... keyValuePairs) {
    if (keyValuePairs.length % 2 != 0) {
      throw new IllegalArgumentException(
          "_datrixOrderedMap requires an even number of arguments (key, value pairs), got "
              + keyValuePairs.length);
    }
    Map<String, Object> result = new LinkedHashMap<>();
    for (int i = 0; i < keyValuePairs.length; i += 2) {
      result.put((String) keyValuePairs[i], keyValuePairs[i + 1]);
    }
    return result;
  }
}
